var l=[{title:`Часові масштаби`,text:`Мікроцикл: це короткий період, що повторюється, часто тиждень. Мезоцикл: це блок із кількох тижнів з одним головним фокусом. Макроцикл охоплює довший сезон чи період цілі. Ці назви допомагають планувати, а їхня тривалість різниться від людини до людини.`},{title:`Три підходи`,text:`Лінійна прогресія повільно змінює змінні в одному загальному напрямку, наприклад від більшої кількості повторень із легшими навантаженнями до меншої з важчими. Хвилеподібне тренування частіше змінює цілі за повтореннями чи інтенсивність, наприклад важко в понеділок і помірно в четвер. Блокова періодизація проходить фази одна за одною, кожна зосереджена на певній здатності.`},{title:`Що показують дослідження`,text:`Дослідження, що порівнюють плани з однаковим обсягом, знаходять можливі переваги в силі для періодизованого тренування над неперіодизованим, а для хвилеподібних планів у тренованих людей. Відмінності в рості м’язів менш послідовні. Позиційна заява ACSM 2026 не виявила стабільної користі для росту м’язів лише від додавання періодизації. Складніший план не є автоматично кращим.`},{title:`Приклад`,text:`Як початківець, повторюйте невеликий набір основних вправ шість тижнів і повільно нарощуйте повторення чи навантаження. Ускладнюйте вправу, коли покращується техніка. Досвідченіші атлети можуть робити три тижні практики з більшим обсягом, потім важчу фазу та легший тиждень відновлення залежно від того, як вони реагують.`},{title:`Як це працює в TrainUp`,text:`Ваш план охоплює 4 тижні, а тиждень 4 є легшим тижнем розвантаження. Ваша ціль, рівень підготовки та зворотний зв’язок важать більше за вигадливий календар. Новий план з’являється лише коли ви його перегенеровуєте, і він змінюється на один крок за раз на основі ваших останніх тренувань.`}];var i=[{label:`Систематичний огляд періодизації та результатів тренувань`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`},{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Рекомендації ACSM щодо моделі прогресії`,url:`https://pubmed.ncbi.nlm.nih.gov/11828249/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};